contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 credChainId_,
        uint256 credId_,
        string calldata verificationType_,
        address protocolFeeDestination_
    ) public {
        require(protocolFeeDestination_ != address(0), "zero recipient");
        c.initialize(credChainId_, credId_, verificationType_, protocolFeeDestination_);

        uint256 tokenIdCounter = c.tokenIdCounter();
        uint256 credChainId = c.credChainId();
        uint256 credId = c.credId();
        string memory name = c.name();
        string memory symbol = c.symbol();
        address protocolFeeDest = c.protocolFeeDestination();

        assert(
            tokenIdCounter == 1 &&
            credChainId == credChainId_ &&
            credId == credId_ &&
            keccak256(bytes(name)) == keccak256(bytes(string(abi.encodePacked("Phi Cred-", _toString(credId_), " on Chain-", _toString(credChainId_))))) &&
            keccak256(bytes(symbol)) == keccak256(bytes(string(abi.encodePacked("PHI-", _toString(credId_), "-", _toString(credChainId_))))) &&
            protocolFeeDest == protocolFeeDestination_
        );
    }

    function _toString(uint256 value) private pure returns (string memory) {
        if (value == 0) return "0";
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }

    receive() external payable {}
}

